const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Pakistan boundary
  const pakistan = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Pakistan'))
    .geometry();

  // Time periods
  const jan2018Start = '2018-01-01';
  const jan2018End = '2018-01-31';
  const aug2018Start = '2018-08-01';
  const aug2018End = '2018-08-31';

  // Load MODIS ET data (8-day product, unit: kg/m²/8day)
  const etCollection = ee.ImageCollection('MODIS/006/MOD16A2');

  // Get January 2018 data
  const janCol = etCollection
    .filterDate(jan2018Start, jan2018End)
    .filterBounds(pakistan)
    .select('ET');

  // Get August 2018 data
  const augCol = etCollection
    .filterDate(aug2018Start, aug2018End)
    .filterBounds(pakistan)
    .select('ET');

  // Check collection sizes
  const janSize = janCol.size().getInfo();
  const augSize = augCol.size().getInfo();

  console.log(`January 2018 images: ${janSize}`);
  console.log(`August 2018 images: ${augSize}`);

  if (janSize === 0 || augSize === 0) {
    console.log('Missing data for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Calculate mean ET for each period
  const janET = janCol.mean();
  const augET = augCol.mean();

  // Reduce to get mean values over Pakistan
  const janStats = janET.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: pakistan,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const augStats = augET.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: pakistan,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const janMean = janStats.ET_mean;
  const janCount = janStats.ET_count;
  const augMean = augStats.ET_mean;
  const augCount = augStats.ET_count;

  console.log(`January 2018 - Mean ET: ${janMean}, Valid pixels: ${janCount}`);
  console.log(`August 2018 - Mean ET: ${augMean}, Valid pixels: ${augCount}`);

  // Check for no valid pixels
  if (janCount === 0 || augCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for invalid calculations
  if (janMean === null || janMean === undefined || isNaN(janMean) ||
      augMean === null || augMean === undefined || isNaN(augMean)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare and determine answer
  console.log(`Change: ${((augMean - janMean) / janMean * 100).toFixed(2)}%`);

  if (augMean > janMean) {
    console.log('August ET is higher than January ET.');
    console.log('<answer>A</answer>');
  } else {
    console.log('August ET is not higher than January ET.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
